"""Quantized solution for Qwen/Qwen3-4B using bitsandbytes 4-bit NF4."""

from __future__ import annotations

from typing import Any

import torch
from transformers import AutoModelForCausalLM, BitsAndBytesConfig

MODEL_ID = "Qwen/Qwen3-4B"
REF_BYTES = 8_044_936_192

_COMPRESSED_BYTES: int | None = None


def _iter_tensors(obj: Any):
    """Yield tensors recursively from arbitrary Python containers."""
    if isinstance(obj, torch.Tensor):
        yield obj
        return
    if isinstance(obj, dict):
        for value in obj.values():
            yield from _iter_tensors(value)
        return
    if isinstance(obj, (list, tuple, set)):
        for value in obj:
            yield from _iter_tensors(value)
        return

    # bitsandbytes quant_state objects are usually dataclass-like.
    if hasattr(obj, "__dict__"):
        for value in vars(obj).values():
            yield from _iter_tensors(value)


def _estimate_model_storage_bytes(model: torch.nn.Module) -> int:
    """Estimate model storage by summing unique tensor storages.

    Includes parameters, buffers, and extra bitsandbytes quantization metadata.
    """
    seen_storages: set[tuple[int, int]] = set()
    total = 0

    def add_tensor(tensor: torch.Tensor) -> None:
        nonlocal total
        if not isinstance(tensor, torch.Tensor) or tensor.is_meta:
            return
        storage = tensor.untyped_storage()
        key = (int(storage.data_ptr()), int(storage.nbytes()))
        if key in seen_storages:
            return
        seen_storages.add(key)
        total += int(storage.nbytes())

    for tensor in model.parameters():
        add_tensor(tensor)
    for tensor in model.buffers():
        add_tensor(tensor)

    # Capture bitsandbytes quantization state tensors that are not always
    # registered as parameters/buffers.
    for module in model.modules():
        weight = getattr(module, "weight", None)
        quant_state = getattr(weight, "quant_state", None)
        if quant_state is not None:
            for tensor in _iter_tensors(quant_state):
                add_tensor(tensor)

    return int(total)


def _to_device_map(device: Any) -> Any:
    if isinstance(device, torch.device):
        return {"": str(device)}
    if isinstance(device, str):
        return {"": device}
    return device


def load_model(device: Any = "cuda"):
    """Load Qwen3-4B quantized to 4-bit NF4."""
    global _COMPRESSED_BYTES

    quant_config = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_use_double_quant=True,
        bnb_4bit_compute_dtype=torch.float16,
    )

    model = AutoModelForCausalLM.from_pretrained(
        MODEL_ID,
        quantization_config=quant_config,
        torch_dtype=torch.float16,
        device_map=_to_device_map(device),
        low_cpu_mem_usage=True,
    )
    model.eval()

    _COMPRESSED_BYTES = _estimate_model_storage_bytes(model)
    return model


def get_compressed_size() -> int:
    """Return actual loaded quantized storage bytes."""
    if _COMPRESSED_BYTES is None:
        raise RuntimeError("Quantized model has not been loaded yet. Call load_model() first.")
    if _COMPRESSED_BYTES <= 0:
        raise RuntimeError(f"Invalid compressed size computed: {_COMPRESSED_BYTES}")
    return int(_COMPRESSED_BYTES)

"""Round-1 quantization baseline for Qwen/Qwen3-4B.

Strategy:
- Load with bitsandbytes NF4 4-bit weight quantization (double quant enabled).
- Keep the model interface compatible with AutoModelForCausalLM.
- Report compressed size using actual tensor storage bytes from the quantized
  state dict, deduplicating shared/tied storages.
"""

from __future__ import annotations

import json
from pathlib import Path

import torch
from transformers import AutoModelForCausalLM, BitsAndBytesConfig

MODEL_ID = "Qwen/Qwen3-4B"
_SIZE_CACHE_PATH = Path(__file__).with_name(".qwen3_4b_nf4_size.json")

# Fallback measured on this exact setup (transformers 5.4.0 + bnb 0.49.2).
# Used only if size has not been measured yet in this process and no cache is
# present on disk.
_FALLBACK_COMPRESSED_BYTES = 2_652_937_335

_MODEL = None
_COMPRESSED_BYTES = None


def _quant_config() -> BitsAndBytesConfig:
    return BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_use_double_quant=True,
        bnb_4bit_compute_dtype=torch.float16,
    )


def _normalize_device_map(device) -> str:
    if isinstance(device, torch.device):
        return str(device)
    return str(device)


def _unique_state_dict_storage_bytes(model) -> int:
    total = 0
    seen = set()
    for tensor in model.state_dict().values():
        if not torch.is_tensor(tensor):
            continue
        storage = tensor.untyped_storage()
        key = (storage.data_ptr(), storage.nbytes())
        if key in seen:
            continue
        seen.add(key)
        total += int(storage.nbytes())
    return total


def _read_cached_size():
    if not _SIZE_CACHE_PATH.exists():
        return None
    try:
        data = json.loads(_SIZE_CACHE_PATH.read_text())
        value = int(data.get("compressed_bytes", 0))
        if value > 0:
            return value
    except Exception:
        return None
    return None


def _write_cached_size(size_bytes: int) -> None:
    payload = {"compressed_bytes": int(size_bytes)}
    _SIZE_CACHE_PATH.write_text(json.dumps(payload))


def load_model(device="cuda"):
    """Load Qwen3-4B with 4-bit NF4 quantization."""
    global _MODEL, _COMPRESSED_BYTES

    if _MODEL is not None:
        return _MODEL

    device_map = _normalize_device_map(device)
    model = AutoModelForCausalLM.from_pretrained(
        MODEL_ID,
        dtype=torch.float16,
        quantization_config=_quant_config(),
        device_map=device_map,
    )
    model.eval()

    _MODEL = model
    _COMPRESSED_BYTES = _unique_state_dict_storage_bytes(model)
    _write_cached_size(_COMPRESSED_BYTES)
    return _MODEL


def get_compressed_size() -> int:
    """Return compressed model size in bytes."""
    global _COMPRESSED_BYTES

    if _COMPRESSED_BYTES is not None and _COMPRESSED_BYTES > 0:
        return int(_COMPRESSED_BYTES)

    cached = _read_cached_size()
    if cached is not None:
        _COMPRESSED_BYTES = cached
        return int(_COMPRESSED_BYTES)

    # If size is requested before load_model(), try measuring directly.
    try:
        if torch.cuda.is_available():
            load_model(device="cuda:0")
            if _COMPRESSED_BYTES is not None:
                return int(_COMPRESSED_BYTES)
    except Exception:
        pass

    return int(_FALLBACK_COMPRESSED_BYTES)
